MultiLanguageSpellData['ru'][53490] = {name = "Ослиное упрямство", additional_info = "{Мгновенное действие} {Восстановление: 3 мин}\n[q]Снимает замедляющие передвижение эффекты и эффекты, вызывающие потерю контроля над питомцем. Уменьшает урон, получаемый питомцем, на 20% на 12 сек."}
