MultiLanguageSpellData['ru'][60017] = {name = "Кровожадность", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Мгновенная атака, наносящая цели 4 ед. урона. Кроме того, следующие 0 успешные атаки ближнего боя:успешных атак ближнего боя восстанавливают 1,5% максимального запаса здоровья. Время действия эффекта – до отмены. Урон зависит от силы атаки."}
MultiLanguageSpellData['ru'][60018] = {name = "Сокрушение", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Удар, повреждающий доспех противника и накладывающий эффект \"Раскол брони\". Удар также наносит 50% урона от оружия и по 90 за каждый действующий эффект \"Раскол брони\". Этот эффект может суммироваться до 5 раз."}
